def make_node_id(kind: str, qualified_name: str, start_line: int) -> str:
        base_id = symbol_node_id(kind, rel_path, qualified_name)
        prior = used_ids.get(base_id)
        if prior is None:
            used_ids[base_id] = (rel_path, start_line)
            return base_id
        if prior == (rel_path, start_line):
            return base_id
        return f"{base_id}:L{start_line}"

def add_node(self, node: GraphNode) -> GraphNode:
        existing = self.nodes.get(node.id)
        if existing is not None:
            return existing
        self.nodes[node.id] = node
        return node

def get_or_create_external(self, dotted_name: str) -> GraphNode:
        node_id = external_node_id(dotted_name)
        existing = self.nodes.get(node_id)
        if existing is not None:
            return existing
        node = GraphNode(
            id=node_id,
            kind=EXTERNAL,
            name=dotted_name.rsplit(".", 1)[-1],
            qualified_name=dotted_name,
            external=True,
        )
        return self.add_node(node)

class CodeGraph:
    nodes: dict[str, GraphNode] = field(default_factory=dict)
    edges: list[GraphEdge] = field(default_factory=list)

    def add_node(self, node: GraphNode) -> GraphNode:
        existing = self.nodes.get(node.id)
        if existing is not None:
            return existing
        self.nodes[node.id] = node
        return node

    def add_edge(self, edge: GraphEdge) -> None:
        self.edges.append(edge)

    def get_or_create_external(self, dotted_name: str) -> GraphNode:
        node_id = external_node_id(dotted_name)
        existing = self.nodes.get(node_id)
        if existing is not None:
            return existing
        node = GraphNode(
            id=node_id,
            kind=EXTERNAL,
            name=dotted_name.rsplit(".", 1)[-1],
            qualified_name=dotted_name,
            external=True,
        )
        return self.add_node(node)

def walk(node: ts.Node) -> None:
        # If this is a block node belonging to a function/method/callable, prune it
        parent = node.parent
        parent_type = parent.type if parent else None

        if is_block_node(node.type):
            if is_callable_parent(parent_type):
                blocks_to_replace.append((node.start_byte, node.end_byte))
                return
            # If parent is a class, we want to walk its children to prune methods inside
            if parent_type and "class" in parent_type.lower():
                for child in node.children:
                    walk(child)
                return
            # For general top-level or control flow blocks inside functions
            blocks_to_replace.append((node.start_byte, node.end_byte))
            return

        for child in node.children:
            walk(child)

def prune_signatures(filepath: str, code: bytes) -> str:
    """Returns the code with internal block logic replaced by placeholders."""
    path = Path(filepath)
    ext = path.suffix.lower()
    lang_id = EXTENSION_TO_LANGUAGE.get(ext)
    if not lang_id:
        return code.decode("utf-8", errors="replace")

    spec = get_spec(lang_id)
    if not spec:
        return code.decode("utf-8", errors="replace")

    parser = ts.Parser(spec.language)
    tree = parser.parse(code)

    if tree.root_node.has_error:
        logging.warning("Syntax error detected in %s, falling back to raw code.", filepath)
        return code.decode("utf-8", errors="replace")

    blocks_to_replace: list[tuple[int, int]] = []

    def walk(node: ts.Node) -> None:
        # If this is a block node belonging to a function/method/callable, prune it
        parent = node.parent
        parent_type = parent.type if parent else None

        if is_block_node(node.type):
            if is_callable_parent(parent_type):
                blocks_to_replace.append((node.start_byte, node.end_byte))
                return
            # If parent is a class, we want to walk its children to prune methods inside
            if parent_type and "class" in parent_type.lower():
                for child in node.children:
                    walk(child)
                return
            # For general top-level or control flow blocks inside functions
            blocks_to_replace.append((node.start_byte, node.end_byte))
            return

        for child in node.children:
            walk(child)

    walk(tree.root_node)

    # Sort blocks by start byte descending to replace without shifting earlier offsets
    blocks_to_replace.sort(key=lambda x: x[0], reverse=True)

    placeholder = get_placeholder(ext)
    mutated_code = bytearray(code)

    for start, end in blocks_to_replace:
        if ext == ".py":
            replacement = b"\n    " + placeholder + b"\n"
        else:
            replacement = b" { " + placeholder + b" }"

        mutated_code[start:end] = replacement

    return mutated_code.decode("utf-8", errors="replace")

def extract_map(filepath: str, code: bytes) -> str:
    """Extracts module linkages (imports) and API surface boundaries (exports, top-level classes)."""
    path = Path(filepath)
    ext = path.suffix.lower()
    lang_id = EXTENSION_TO_LANGUAGE.get(ext)
    if not lang_id:
        return code.decode("utf-8", errors="replace")

    spec = get_spec(lang_id)
    if not spec:
        return code.decode("utf-8", errors="replace")

    parser = ts.Parser(spec.language)
    tree = parser.parse(code)

    if tree.root_node.has_error:
        logging.warning("Syntax error detected in %s, falling back to raw code.", filepath)
        return code.decode("utf-8", errors="replace")

    output_parts: list[str] = []

    for node in tree.root_node.children:
        nt = node.type.lower()
        if "import" in nt or "require" in nt:
            output_parts.append(code[node.start_byte:node.end_byte].decode("utf-8", errors="replace"))
        elif "class" in nt or "export" in nt or "interface" in nt or "function" in nt:
            node_code = code[node.start_byte:node.end_byte]
            pruned_node = prune_signatures(filepath, node_code)
            output_parts.append(pruned_node)

    return "\n\n".join(output_parts)

def compose_from_base() -> str:
        try:
            content = layers[-1][0].read_bytes().decode("utf-8")
            for path, strategy in reversed(layers[:-1]):
                layer_content = path.read_bytes().decode("utf-8")
                if strategy == "prepend":
                    content = f"{layer_content}\n\n{content}"
                elif strategy == "append":
                    content = f"{content}\n\n{layer_content}"
                elif strategy == "wrap":
                    placeholder = "{CORE_TEMPLATE}"
                    if placeholder not in layer_content:
                        raise TemplateResolutionError(
                            f"Wrap layer {path} is missing {placeholder}"
                        )
                    content = layer_content.replace(placeholder, content)
                else:
                    raise TemplateResolutionError(
                        f"Unknown template composition strategy '{strategy}' in {path}"
                    )
        except (OSError, UnicodeError) as exc:
            raise TemplateResolutionError(
                f"Failed to read template layer for '{template_name}': {exc}"
            ) from exc
        return content

def resolve_template_content(template_name: str, repo_root: Path) -> str | None:
    """Resolve and compose template content through the project layer stack."""
    if not _is_safe_component(template_name):
        return None

    layers: list[tuple[Path, str]] = []

    def compose_from_base() -> str:
        try:
            content = layers[-1][0].read_bytes().decode("utf-8")
            for path, strategy in reversed(layers[:-1]):
                layer_content = path.read_bytes().decode("utf-8")
                if strategy == "prepend":
                    content = f"{layer_content}\n\n{content}"
                elif strategy == "append":
                    content = f"{content}\n\n{layer_content}"
                elif strategy == "wrap":
                    placeholder = "{CORE_TEMPLATE}"
                    if placeholder not in layer_content:
                        raise TemplateResolutionError(
                            f"Wrap layer {path} is missing {placeholder}"
                        )
                    content = layer_content.replace(placeholder, content)
                else:
                    raise TemplateResolutionError(
                        f"Unknown template composition strategy '{strategy}' in {path}"
                    )
        except (OSError, UnicodeError) as exc:
            raise TemplateResolutionError(
                f"Failed to read template layer for '{template_name}': {exc}"
            ) from exc
        return content

    override = (
        repo_root
        / ".specify"
        / "templates"
        / "overrides"
        / f"{template_name}.md"
    )
    if override.is_file():
        layers.append((override, "replace"))
        return compose_from_base()

    presets_dir = repo_root / ".specify" / "presets"
    for preset_id in _sorted_preset_ids(presets_dir):
        layer = _preset_template_layer(presets_dir / preset_id, template_name)
        if layer is not None:
            layers.append(layer)
            if layer[1] == "replace":
                return compose_from_base()

    extensions_dir = repo_root / ".specify" / "extensions"
    for extension_id in _sorted_extension_ids(extensions_dir):
        extension_dir = extensions_dir / extension_id
        candidate = _conventional_template(extension_dir, template_name)
        if candidate is not None:
            layers.append((candidate, "replace"))
            return compose_from_base()

    core = repo_root / ".specify" / "templates" / f"{template_name}.md"
    if core.is_file():
        layers.append((core, "replace"))
        return compose_from_base()

    if not layers:
        return None

    raise TemplateResolutionError(
        f"Template '{template_name}' has composing layers but no replace base"
    )
